import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { projectKeyFromName, uniqueSlug } from "@/lib/slug";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  NotFoundError,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  ArchiveProjectInput,
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { OrgId, Page, ProjectId } from "@/types/common";
import { hasRoleAtLeast } from "@/types/member";
import type { Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/**
 * Whether `actor` may see `project` at all. A `private` project is visible
 * only to admins/owners, platform staff, its lead, or an explicit project
 * member; `org` and `public` projects are visible to anyone in the org.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.orgId !== project.orgId) return false;
  if (actor.isPlatformStaff === true) return true;
  if (hasRoleAtLeast(actor.role, "admin")) return true;
  if (project.leadId === actor.userId) return true;

  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

function requireVisible(
  actor: Actor,
  project: Project,
  entity: string,
  id: string,
): Promise<void> {
  return canViewProject(actor, project).then((visible) => {
    if (!visible) throw new NotFoundError(entity, id);
  });
}

/**
 * Every private project in the org that `actor` is not allowed to see, for
 * excluding them (and, by extension, their issues) from list queries.
 */
export async function hiddenPrivateProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  if (actor.isPlatformStaff === true || hasRoleAtLeast(actor.role, "admin")) {
    return [];
  }

  const privateProjects = await projectRepo.listPrivateProjectIdsAndLeads(orgId);
  if (privateProjects.length === 0) return [];

  const memberProjectIds = new Set(
    await projectMemberRepo.listProjectIdsForUser(orgId, actor.userId),
  );

  return privateProjects
    .filter(
      (project) =>
        project.leadId !== actor.userId && !memberProjectIds.has(project.id),
    )
    .map((project) => project.id);
}

